const RECT_LABEL_RIBALTA = { x:218, y:18, w:265, h:206 };
// Ribalta → slide mappa, per range di numero (associazione per ribalta, NON per
// reparto: i range non coincidono coi reparti e i reparti possono cambiare).
// Fonte: casella di testo con il range in ogni slide di Mappa_percorsi.pptx.
const RIBALTA_SLIDE_RANGES = [
  { ed:'PNT1', da: 1, a:31, slide: 6 },
  { ed:'PNT1', da:32, a:42, slide: 8 },
  { ed:'PNT1', da:43, a:49, slide: 9 },
  { ed:'PNT1', da:50, a:61, slide:10 },
  { ed:'PNT1', da:62, a:72, slide:11 },
  { ed:'PNT1', da:73, a:81, slide:12 },
  { ed:'PNT1', da:82, a:90, slide: 7 },
  { ed:'PNT2', da: 1, a:18, slide:13 },
  { ed:'PNT2', da:19, a:48, slide:14 },
  { ed:'PNT2', da:49, a:49, slide:15 },
];
// 'PNT1-07' → 6 ; id non riconosciuto → null (stampa foglio senza mappa)
function _ribaltaSlide(id){
  const m = /^(PNT[12])-(\d+)$/.exec(String(id || '').trim().toUpperCase());
  if (!m) return null;
  const n = parseInt(m[2], 10);
  const r = RIBALTA_SLIDE_RANGES.find(x => x.ed === m[1] && n >= x.da && n <= x.a);
  return r ? r.slide : null;
}

