// ── HELPER: rileva tipo da id ────────────────────────────────────────────────
function _portRilevaTipo(id) {
  if (_PORT_RE_CONTAINER.test(id)) return 'container';
  if (_PORT_RE_CASSA.test(id))     return 'cassa';
  return null;
}

// ── HELPER: veicolo già presente nel sito? ───────────────────────────────────
// Unico controllo duplicati per TUTTI gli ingressi da portineria (cerca posto,
// conferma posto, invio diretto a ribalta). Ritorna null se il veicolo è libero
// di entrare, altrimenti una stringa HTML che descrive dove si trova.
// Se la verifica non è possibile (rete/permessi) lancia un errore: il chiamante
// deve BLOCCARE l'ingresso, non proseguire.
async function _portVerificaPresenza(veicolo){
  const v = window.normalizzaId(veicolo);
  // 1. Parcheggio (stato locale, confronto normalizzato)
  const inSpot = Object.entries(window.spots || {})
    .find(([, s]) => s && s.occupied && window.normalizzaId(s.plate) === v);
  if (inSpot) return `<strong>${v}</strong> è già parcheggiato nel posto <strong>${inSpot[0]}</strong>.`;
  // 2. Ribalta (tutti i doc con quella targa, non solo il primo)
  const ribSnap = await getDocs(query(collection(window.db, 'ribalte'), where('plate', '==', v)));
  const ribOcc  = ribSnap.docs.find(d => d.data().occupied);
  if (ribOcc) return `<strong>${v}</strong> è già alla ribalta <strong>${ribOcc.id}</strong>.`;
  // 3. Missione aperta (creata o in attesa)
  const prenSnap = await getDocs(query(collection(window.db, 'prenotazioni'), where('plate', '==', v)));
  const prenAp   = prenSnap.docs.find(d => ['creata', 'in_attesa'].includes(d.data().stato));
  if (prenAp) {
    const pd = prenAp.data();
    const dest = pd.destinazione ? ` → <strong>${pd.destinazione}</strong>` : '';
    return `<strong>${v}</strong> ha una missione aperta${dest}.`;
  }
  return null;
}
const _PORT_MSG_VERIFICA_KO = '⚠ Impossibile verificare se il veicolo è già presente (errore di rete). Riprova.';

// ── CERCA POSTO ──────────────────────────────────────────────────────────────
async function portineriaCerca() {
  const veicolo = window.normalizzaId(document.getElementById('port-veicolo').value || '');
  const stato   = document.getElementById('port-stato').value;
  const resEl   = document.getElementById('port-result');

  _portSpotSuggerito = null;
  document.getElementById('port-btn-conferma').disabled = true;
  document.getElementById('port-btn-stampa').disabled   = true;

  if (!veicolo) {
    resEl.innerHTML = '<div class="port-err">⚠ Inserisci l\'identificativo del veicolo.</div>';
    return;
  }

  const tipo = _portRilevaTipo(veicolo);
  if (!tipo) {
    resEl.innerHTML = '<div class="port-err">⚠ Formato non riconosciuto.<br>Container: 4 lettere + 7 cifre (es. MSCU1234567)<br>oppure 2 lettere + 3 cifre + 2 lettere / 1–3 cifre (es. AB123CD, AB1234)<br>Cassa: 3 cifre (es. 042)</div>';
    return;
  }

  // ── VERIFICA DUPLICATO ──────────────────────────────────────────
  resEl.innerHTML = '<div class="port-err" style="opacity:.6">🔍 Verifica in corso…</div>';

  try {
    const _dup = await _portVerificaPresenza(veicolo);
    if (_dup) {
      resEl.innerHTML = `<div class="port-err">⚠ ${_dup}<br>Impossibile assegnare un posto parcheggio.</div>`;
      return;
    }
  } catch (_portE) {
    console.error('Verifica duplicato portineria:', _portE);
    resEl.innerHTML = `<div class="port-err">${_PORT_MSG_VERIFICA_KO}</div>`;
    return;
  }
  // ─────────────────────────────────────────────────────────────────────────

  // Cerca primo posto libero compatibile
  const candidati = Object.entries(SPOT_CRITERI)
    .filter(([id, crit]) => crit.tipo === tipo && crit.stato === stato)
    .map(([id]) => id)
    .sort(); // ordine alfanumerico: A01, A02 ... D15

  const posto = candidati.find(id => window.spots[id] && !window.spots[id].occupied);

  if (!posto) {
    resEl.innerHTML = `<div class="port-err">⚠ Nessun posto libero disponibile per ${tipo} <strong>${stato}</strong>.<br>Tutti i posti compatibili sono occupati.</div>`;
    return;
  }

  _portSpotSuggerito = posto;
  _portVeicolo = veicolo;
  _portStato   = stato;
  _portTipo    = tipo;

  const zona     = posto[0];
  const slideIdx = SPOT_SLIDE[posto];

  // Istruzioni percorso per zona
  const istruzioni = {
    'B': ['Esci dall\'area portineria verso destra', 'Percorri il viale principale in direzione nord', 'Il Parcheggio BLU è sulla destra all\'ingresso dell\'area'],
    'A': ['Esci dall\'area portineria verso destra', 'Percorri il viale principale in direzione nord', 'Il Parcheggio VERDE è a sinistra prima dell\'edificio principale'],
    'C': ['Esci dall\'area portineria verso sinistra', 'Percorri il perimetro esterno in senso antiorario', 'La Zona C è sul lato ovest dell\'impianto'],
    'D': ['Esci dall\'area portineria verso sinistra', 'Percorri il perimetro esterno fino al fondo', 'La Zona D è sul lato sud-ovest dell\'impianto'],
  };
  const steps = istruzioni[zona] || ['Seguire indicazioni sulla mappa stampata'];

  resEl.innerHTML = `
    <div class="port-ok">
      <div class="port-ok-badge">Posto suggerito</div>
      <div class="port-ok-spot">${posto}</div>
      <div class="port-ok-info">
        Veicolo: <strong>${veicolo}</strong> &nbsp;·&nbsp;
        Tipo: <strong>${tipo.charAt(0).toUpperCase()+tipo.slice(1)}</strong> &nbsp;·&nbsp;
        Stato: <strong>${stato.charAt(0).toUpperCase()+stato.slice(1)}</strong>
      </div>
      <div class="port-ok-istruzioni">
        <strong>Percorso:</strong>
        <ol>${steps.map(s=>'<li>'+s+'</li>').join('')}</ol>
      </div>
    </div>`;

  document.getElementById('port-btn-conferma').disabled = false;
  document.getElementById('port-btn-stampa').disabled   = false;
}

// ── RESET ─────────────────────────────────────────────────────────────────────
function porteriaReset() {
  _portSpotSuggerito = null;
  _portVeicolo = null;
  _portStato   = null;
  _portTipo    = null;
  document.getElementById('port-veicolo').value = '';
  document.getElementById('port-stato').value   = 'pieno';
  document.getElementById('port-result').innerHTML = '';
  document.getElementById('port-btn-conferma').disabled = true;
  document.getElementById('port-btn-stampa').disabled   = true;
  // Reset modalità ribalta
  const _flag = document.getElementById('port-rib-flag');
  if (_flag) _flag.checked = false;
  if (typeof portRibToggle === 'function') portRibToggle(false);
}

// ── CONFERMA ASSEGNAZIONE ────────────────────────────────────────────────────
async function porteriaConferma() {
  if (!_portSpotSuggerito || !_portVeicolo) return;

  const id     = _portSpotSuggerito;
  const veicolo = _portVeicolo;
  const btn    = document.getElementById('port-btn-conferma');

  // Verifica che il posto sia ancora libero (race condition)
  if (window.spots[id] && window.spots[id].occupied) {
    document.getElementById('port-result').innerHTML =
      '<div class="port-err">⚠ Il posto è stato occupato nel frattempo. Clicca "Cerca Posto" per un nuovo suggerimento.</div>';
    _portSpotSuggerito = null;
    document.getElementById('port-btn-conferma').disabled = true;
    document.getElementById('port-btn-stampa').disabled   = true;
    return;
  }

  btn.disabled = true;
  btn.textContent = 'Assegnazione in corso...';

  // Ricontrollo presenza: il veicolo può essere stato inserito da altri dopo "Cerca"
  try {
    const _dup = await _portVerificaPresenza(veicolo);
    if (_dup) {
      document.getElementById('port-result').innerHTML =
        `<div class="port-err">⚠ ${_dup}<br>Assegnazione annullata.</div>`;
      _portSpotSuggerito = null;
      document.getElementById('port-btn-stampa').disabled = true;
      btn.textContent = '✔ Conferma Assegnazione';
      return;
    }
  } catch (_portE) {
    console.error('Verifica duplicato portineria:', _portE);
    document.getElementById('port-result').innerHTML = `<div class="port-err">${_PORT_MSG_VERIFICA_KO}</div>`;
    btn.disabled = false;
    btn.textContent = '✔ Conferma Assegnazione';
    return;
  }

  try {
    const now = new Date();
    await setDoc(doc(window.db, 'spots', id), {
      occupied: true,
      plate:    veicolo,
      since:    now,
      user:     window.currentUser.email,
      full:     _portStato === 'pieno',
    });
    await window.logHistory({
      spot:        id,
      action:      'checkin',
      plate:       veicolo,
      origine:     'portineria',
      full:        _portStato === 'pieno',
    });

    // Aggiorna stato locale subito (il listener aggiornerà dopo)
    if (window.spots[id]) {
      window.spots[id].occupied = true;
      window.window.spots[id].plate    = veicolo;
      window.spots[id].since    = now;
    }

    window.showToast('Posto ' + id + ' assegnato a ' + veicolo);
    // Resetta solo i campi input, mantieni risultato visibile per la stampa
    document.getElementById('port-veicolo').value = '';
    document.getElementById('port-stato').value   = 'pieno';
    // Aggiorna testo bottone e lascia stampa attiva
    document.getElementById('port-btn-conferma').textContent = '✔ Assegnato';
    document.getElementById('port-btn-stampa').disabled = false;
    btn.disabled = true;

  } catch(e) {
    console.error('Errore assegnazione portineria:', e);
    window.showToast('Errore durante l\'assegnazione. Riprova.', 'error');
    btn.disabled  = false;
    btn.textContent = '✔ Conferma Assegnazione';
  }
}

// ── STAMPA MAPPA PERCORSO ────────────────────────────────────────────────────
function porteriaStampa() {
  if (!_portSpotSuggerito) return;

  const posto    = _portSpotSuggerito;
  const slideIdx = SPOT_SLIDE[posto];
  const imgSrc   = MAPPE_PERCORSO[slideIdx];
  if (!imgSrc) {
    window.showToast('Mappa percorso non configurata per il posto ' + posto + '.', 'error');
    return;
  }

  // Crea finestra di stampa con canvas: disegna immagine + etichetta posto
  const printWin = window.open('', '_blank', 'width=1200,height=900');
  if (!printWin) {
    window.showToast('Popup bloccato. Abilita i popup per questo sito.', 'error');
    return;
  }

  printWin.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Mappa Percorso – Posto ${posto}</title>
  <style>
    @page { size: A4 landscape; margin: 0; }
    * { margin:0; padding:0; box-sizing:border-box; }
    body { width:297mm; height:210mm; overflow:hidden; background:#fff; }
    canvas { display:block; width:297mm; height:210mm; }
    .no-print { position:fixed; top:10px; right:10px; z-index:999;
                background:#A4D200; color:#1a1a1a; border:none; padding:10px 20px;
                font-size:16px; font-weight:700; border-radius:6px; cursor:pointer; }
    @media print { .no-print { display:none; } }
  </style>
</head>
<body>
  <button class="no-print" onclick="window.print()">🖨 Stampa</button>
  <canvas id="printCanvas"></canvas>
  <script>
    const canvas = document.getElementById('printCanvas');
    // A4 landscape a 150dpi: 297mm * 5.906px/mm ≈ 1754px, 210mm ≈ 1240px
    // La nostra immagine è 1500x1125 (ratio 4:3) → la adattiamo all'A4 landscape
    canvas.width  = 1754;
    canvas.height = 1240;
    const ctx = canvas.getContext('2d');

    const img = new Image();
    img.onload = function() {
      // Disegna mappa adattata all'intera area canvas
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      // Calcola coordinate rettangolo scalate
      const scaleX = canvas.width  / 1500;
      const scaleY = canvas.height / 1125;
      const rx = Math.round(${RECT_LABEL.x} * scaleX);
      const ry = Math.round(${RECT_LABEL.y} * scaleY);
      const rw = Math.round(${RECT_LABEL.w} * scaleX);
      const rh = Math.round(${RECT_LABEL.h} * scaleY);

      // Rettangolo: sfondo bianco/chiaro con bordo nero
      ctx.fillStyle = '#f8f8f8';
      ctx.fillRect(rx, ry, rw, rh);
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = Math.round(rw * 0.02);
      ctx.strokeRect(rx, ry, rw, rh);

      // Testo nero centrato, font auto-fit per stare su una riga
      const label = '${posto}';
      ctx.fillStyle    = '#000000';
      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      // Calcola font size massimo che fa stare il testo su una riga
      let fontSize = Math.round(rh * 0.55);
      ctx.font = 'bold ' + fontSize + 'px "Barlow Condensed", Arial, sans-serif';
      while (ctx.measureText(label).width > rw * 0.85 && fontSize > 10) {
        fontSize -= 2;
        ctx.font = 'bold ' + fontSize + 'px "Barlow Condensed", Arial, sans-serif';
      }
      ctx.fillText(label, rx + rw/2, ry + rh/2);
    };
    img.src = '${imgSrc}';
  <\/script>
</body>
</html>`);
  printWin.document.close();
}

// ── ESPOSIZIONE GLOBALI ───────────────────────────────────────────────────────
// ── INVIO DIRETTO A RIBALTA: LOGICA ───────────────────────────────────────────

// Elenco completo ribalte di un edificio, da config live (window.REPARTI) con
// fallback statico. Le ribalte sono nominate 'PNT1-01'…'PNT2-49'.
function _portRibalteEdificio(edificio){
  const R = window.REPARTI || {};
  const set = new Set();
  Object.values(R).forEach(arr => (arr||[]).forEach(r => {
    if (typeof r === 'string' && r.indexOf(edificio + '-') === 0) set.add(r);
  }));
  return Array.from(set).sort();
}

// Insieme delle ribalte attualmente occupate (lettura one-off).
async function _portRibalteOccupate(){
  const occ = new Set();
  try {
    const snap = await getDocs(query(collection(window.db, 'ribalte'), where('occupied','==',true)));
    snap.forEach(d => occ.add(d.id));
  } catch(e){ /* rete/permessi: insieme parziale */ }
  // Ribalte riservate come destinazione di missioni/richieste aperte
  try {
    const ps = await getDocs(query(collection(window.db, 'prenotazioni'), where('stato','in',['creata','in_attesa'])));
    ps.forEach(d => { const dst = String(d.data().destinazione || '').trim().toUpperCase(); if (dst && dst !== '—') occ.add(dst); });
  } catch(e){ /* insieme parziale */ }
  // Ribalte con una navetta attiva
  Object.values(window.navette || {}).forEach(n => { if (n.attiva && n.posizione) occ.add(String(n.posizione).trim().toUpperCase()); });
  return occ;
}

// Attiva/disattiva la modalità "invia a ribalta".
function portRibToggle(on){
  _portRibModo = !!on;
  _portRibEdificio    = null;
  _portRibSelezionata = null;
  const panel    = document.getElementById('port-rib-panel');
  const result   = document.getElementById('port-result');
  const actions  = document.querySelector('.port-actions');
  const btnCerca = document.getElementById('port-btn-cerca');
  if (on){
    // In ingresso diretto i container sono di norma pieni
    document.getElementById('port-stato').value = 'pieno';
    if (panel)    panel.style.display = 'block';
    if (result)   result.innerHTML = '';
    if (actions)  actions.style.display = 'none';
    if (btnCerca) btnCerca.style.display = 'none';
    document.querySelectorAll('.port-rib-ebtn').forEach(b => b.classList.remove('active'));
    const ls = document.getElementById('port-rib-liststep'); if (ls) ls.style.display = 'none';
    const li = document.getElementById('port-rib-list');     if (li) li.innerHTML = '';
    const cb = document.getElementById('port-rib-btn-conferma');
    if (cb){ cb.disabled = true; cb.textContent = '✓ Conferma e stampa'; }
  } else {
    if (panel)    panel.style.display = 'none';
    if (actions)  actions.style.display = 'flex';
    if (btnCerca) btnCerca.style.display = '';
  }
}

// Selezione edificio → carica e mostra le sole ribalte libere.
async function portRibEdificio(edificio){
  const veicolo = window.normalizzaId(document.getElementById('port-veicolo').value || '');
  if (_portRilevaTipo(veicolo) !== 'container'){
    document.getElementById('port-result').innerHTML =
      '<div class="port-err">⚠ L\'invio diretto a ribalta è solo per i container.</div>';
    return;
  }
  try {
    const _dup = await _portVerificaPresenza(veicolo);
    if (_dup) {
      document.getElementById('port-result').innerHTML =
        `<div class="port-err">⚠ ${_dup}<br>Impossibile inviarlo a una ribalta.</div>`;
      return;
    }
  } catch (_portE) {
    console.error('Verifica duplicato portineria:', _portE);
    document.getElementById('port-result').innerHTML = `<div class="port-err">${_PORT_MSG_VERIFICA_KO}</div>`;
    return;
  }
  document.getElementById('port-result').innerHTML = '';
  _portRibEdificio = edificio;
  _portRibSelezionata = null;
  document.getElementById('port-rib-btn-conferma').disabled = true;
  document.querySelectorAll('.port-rib-ebtn').forEach(b => b.classList.remove('active'));
  const eb = document.getElementById('port-rib-ed-' + edificio); if (eb) eb.classList.add('active');

  const listStep = document.getElementById('port-rib-liststep');
  const listEl   = document.getElementById('port-rib-list');
  listStep.style.display = 'block';
  listEl.innerHTML = '<div class="port-rib-empty">🔍 Caricamento ribalte libere…</div>';

  const tutte    = _portRibalteEdificio(edificio);
  const occupate = await _portRibalteOccupate();
  const libere   = tutte.filter(r => !occupate.has(r));

  if (!libere.length){
    listEl.innerHTML = '<div class="port-rib-empty">Nessuna ribalta libera in ' + edificio + '.</div>';
    return;
  }
  listEl.innerHTML = libere.map(r =>
    '<button type="button" class="port-rib-rbtn" id="port-rib-r-' + r + '" onclick="portRibSeleziona(\'' + r + '\')">' + r + '</button>'
  ).join('');
}

// Selezione ribalta → evidenzia e abilita conferma.
function portRibSeleziona(id){
  _portRibSelezionata = id;
  document.querySelectorAll('.port-rib-rbtn').forEach(b => b.classList.remove('active'));
  const rb = document.getElementById('port-rib-r-' + id); if (rb) rb.classList.add('active');
  const btn = document.getElementById('port-rib-btn-conferma');
  btn.disabled = false;
  btn.textContent = '✓ Conferma e stampa · ' + id;
}

// Conferma: ricontrolla libera → scrive occupied:true → storico → stampa.
async function portRibConferma(){
  const veicolo = window.normalizzaId(document.getElementById('port-veicolo').value || '');
  const id      = _portRibSelezionata;
  const stato   = document.getElementById('port-stato').value;
  if (!id) return;
  if (_portRilevaTipo(veicolo) !== 'container'){
    document.getElementById('port-result').innerHTML =
      '<div class="port-err">⚠ Targa container non valida.</div>';
    return;
  }
  const btn = document.getElementById('port-rib-btn-conferma');
  btn.disabled = true;
  btn.textContent = 'Invio in corso…';

  try {
    const _dup = await _portVerificaPresenza(veicolo);
    if (_dup) {
      document.getElementById('port-result').innerHTML =
        `<div class="port-err">⚠ ${_dup}<br>Invio a ribalta annullato.</div>`;
      btn.textContent = '✓ Conferma e stampa';
      return;
    }
  } catch (_portE) {
    console.error('Verifica duplicato portineria:', _portE);
    document.getElementById('port-result').innerHTML = `<div class="port-err">${_PORT_MSG_VERIFICA_KO}</div>`;
    btn.disabled = false;
    btn.textContent = '✓ Conferma e stampa';
    return;
  }

  try {
    const dref  = doc(window.db, 'ribalte', id);
    const dsnap = await getDoc(dref);
    if (dsnap.exists() && dsnap.data().occupied){
      document.getElementById('port-result').innerHTML =
        '<div class="port-err">⚠ La ribalta ' + id + ' è stata occupata nel frattempo. Riseleziona l\'edificio.</div>';
      btn.textContent = '✓ Conferma e stampa';
      if (_portRibEdificio) portRibEdificio(_portRibEdificio);
      return;
    }
    const now = new Date();
    // Doc speculare a quello scritto dall'operativo alla liberazione:
    await setDoc(dref, {
      occupied: true,
      plate:    veicolo,
      since:    now,
      user:     window.currentUser.email,
      full:     stato === 'pieno',
    });
    await window.logHistory({
      spot:     id,
      action:   'Ingresso ribalta',
      plate:    veicolo,
      origine:  'portineria',
      full:     stato === 'pieno',
    });
    window.showToast('Container ' + veicolo + ' inviato alla ribalta ' + id);
    document.getElementById('port-result').innerHTML =
      '<div class="port-ok"><div class="port-ok-badge">Inviato a ribalta</div>' +
      '<div class="port-ok-spot">' + id + '</div>' +
      '<div class="port-ok-info">Veicolo: <strong>' + veicolo + '</strong> &nbsp;·&nbsp; Stato: <strong>' +
      (stato.charAt(0).toUpperCase() + stato.slice(1)) + '</strong></div></div>';
    portRibStampa(id);
    btn.textContent = '✔ Inviato';
  } catch(e){
    console.error('Errore invio ribalta:', e);
    window.showToast('Errore durante l\'invio. Riprova.', 'error');
    btn.disabled = false;
    btn.textContent = '✓ Conferma e stampa';
  }
}

// Stampa foglio percorso ribalta (A4 landscape): mappa della slide associata
// alla ribalta + numero ribalta nel riquadro in alto a sinistra. Se la ribalta
// non ha una mappa associata, stampa un foglio con il solo numero ben visibile.
function portRibStampa(id){
  const slide  = _ribaltaSlide(id);
  const imgSrc = slide ? MAPPE_PERCORSO[slide] : null;
  const printWin = window.open('', '_blank', 'width=1200,height=900');
  if (!printWin){ window.showToast('Popup bloccato. Abilita i popup per questo sito.', 'error'); return; }

  if (!imgSrc){
    printWin.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Ribalta ${id}</title>
<style>@page{size:A4 landscape;margin:0}*{margin:0;padding:0;box-sizing:border-box}
body{width:297mm;height:210mm;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:Arial,sans-serif;background:#fff}
.lbl{font-size:28mm;font-weight:800;letter-spacing:4px}.sub{font-size:8mm;margin-top:6mm;color:#333}
.note{position:fixed;bottom:8mm;font-size:5mm;color:#999}
.no-print{position:fixed;top:10px;right:10px;background:#A4D200;border:none;padding:10px 20px;font-size:16px;font-weight:700;border-radius:6px;cursor:pointer}
@media print{.no-print{display:none}}</style></head>
<body><button class="no-print" onclick="window.print()">🖨 Stampa</button>
<div class="lbl">${id}</div><div class="sub">Container in ingresso</div>
<div class="note">Mappa percorso non ancora configurata per questa ribalta</div></body></html>`);
    printWin.document.close();
    return;
  }

  const RL = RECT_LABEL_RIBALTA;
  printWin.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Mappa Percorso – Ribalta ${id}</title>
<style>@page{size:A4 landscape;margin:0}*{margin:0;padding:0;box-sizing:border-box}
body{width:297mm;height:210mm;overflow:hidden;background:#fff}canvas{display:block;width:297mm;height:210mm}
.no-print{position:fixed;top:10px;right:10px;z-index:999;background:#A4D200;color:#1a1a1a;border:none;padding:10px 20px;font-size:16px;font-weight:700;border-radius:6px;cursor:pointer}
@media print{.no-print{display:none}}</style></head>
<body><button class="no-print" onclick="window.print()">🖨 Stampa</button><canvas id="printCanvas"></canvas>
<script>
const canvas=document.getElementById('printCanvas');canvas.width=1754;canvas.height=1240;
const ctx=canvas.getContext('2d');const img=new Image();
img.onload=function(){ctx.drawImage(img,0,0,canvas.width,canvas.height);
const sx=canvas.width/1500,sy=canvas.height/1125;
const rx=Math.round(${RL.x}*sx),ry=Math.round(${RL.y}*sy),rw=Math.round(${RL.w}*sx),rh=Math.round(${RL.h}*sy);
ctx.fillStyle='#f8f8f8';ctx.fillRect(rx,ry,rw,rh);ctx.strokeStyle='#000';ctx.lineWidth=Math.round(rw*0.02);ctx.strokeRect(rx,ry,rw,rh);
const label='${id}';ctx.fillStyle='#000';ctx.textAlign='center';ctx.textBaseline='middle';
let fs=Math.round(rh*0.55);ctx.font='bold '+fs+'px "Barlow Condensed",Arial,sans-serif';
while(ctx.measureText(label).width>rw*0.85&&fs>10){fs-=2;ctx.font='bold '+fs+'px "Barlow Condensed",Arial,sans-serif';}
ctx.fillText(label,rx+rw/2,ry+rh/2);};
img.src='${imgSrc}';
<\/script></body></html>`);
  printWin.document.close();
}

